use std::process::{Child,Command}; use std::sync::{Mutex,OnceLock};
static CHILDREN:OnceLock<Mutex<Vec<Child>>>=OnceLock::new(); fn children()->&'static Mutex<Vec<Child>>{CHILDREN.get_or_init(||Mutex::new(Vec::new()))}
pub fn open_target(target:&str)->Result<String,String>{let key=target.trim().to_lowercase();let(program,args,label):(&str,&[&str],&str)=match key.as_str(){"notepad"|"المفكرة"=>("notepad.exe",&[],"Notepad"),"calculator"|"calc"|"الحاسبة"=>("calc.exe",&[],"Calculator"),"paint"|"mspaint"|"الرسام"=>("mspaint.exe",&[],"Paint"),"explorer"|"file explorer"|"الملفات"=>("explorer.exe",&[],"File Explorer"),_ if key.starts_with("https://")||key.starts_with("http://")=>{let c=Command::new("rundll32.exe").args(["url.dll,FileProtocolHandler",target.trim()]).spawn().map_err(|e|e.to_string())?;children().lock().map_err(|_|"Computer control lock failed".to_string())?.push(c);return Ok(target.trim().to_string())},_=>return Err("For safety, Adam currently opens only approved Windows apps or http/https URLs.".into())};let c=Command::new(program).args(args).spawn().map_err(|e|e.to_string())?;children().lock().map_err(|_|"Computer control lock failed".to_string())?.push(c);Ok(label.into())}
pub fn stop_all(){if let Ok(mut list)=children().lock(){for c in list.iter_mut(){let _=c.kill();}list.clear();}}
